-- FINAL ALL-ACCOUNT RECONCILIATION: employee 2; snapshot 2026-09-15.
-- Management confirmed old arrears can be cleared (Delroy 2025 -> 0).
-- Positive net monthly receipts since Aug 1 qualify for one-time debt relief.
-- Future paid months retain credit; due days 1-15 map to the following month.
-- Convert deferred billing coverage into credit without losing existing credit.
-- APPLY VERSION: commits the reviewed changes and enables reconnection automation.
BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
LOCK TABLE public.customers,public.payments,public.account_ledger_entries,
 public.waiver_requests,public.account_status_history,public.reconnection_requests,
 public.customer_billing_start,public.customer_rate_history IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE final_accounts(customer_id INTEGER PRIMARY KEY,before_balance NUMERIC(14,2),
 target_balance NUMERIC(14,2),before_status TEXT,payment_fingerprint TEXT,monthly_fee NUMERIC(14,2),activation_date DATE) ON COMMIT DROP;
CREATE TEMP TABLE final_schedules(customer_id INTEGER PRIMARY KEY,old_start DATE,deferred_value NUMERIC(14,2)) ON COMMIT DROP;
DO $$ BEGIN
 IF (CURRENT_TIMESTAMP AT TIME ZONE 'America/Jamaica')::DATE<>DATE '2026-09-15' THEN
  RAISE EXCEPTION 'Snapshot date expired. Refresh before applying.';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.employees WHERE employee_id=2 AND role='admin') THEN
  RAISE EXCEPTION 'Employee 2 must be an admin'; END IF;
 IF EXISTS(SELECT 1 FROM final_accounts r LEFT JOIN public.customers c USING(customer_id)
  LEFT JOIN public.customer_billing_status b USING(customer_id)
  WHERE c.customer_id IS NULL OR b.balance IS DISTINCT FROM r.before_balance
   OR c.status IS DISTINCT FROM r.before_status OR c.monthly_fee IS DISTINCT FROM r.monthly_fee
   OR c.activation_date IS DISTINCT FROM r.activation_date OR c.hidden_from_app) THEN
  RAISE EXCEPTION 'Customer balance/status/rate/activation changed. Refresh the review.'; END IF;
 IF EXISTS(SELECT 1 FROM final_schedules r LEFT JOIN public.customer_billing_start b USING(customer_id)
  WHERE b.billing_start_date IS DISTINCT FROM r.old_start) THEN
  RAISE EXCEPTION 'Prepaid billing schedule changed. Refresh the review.'; END IF;
 IF EXISTS(SELECT 1 FROM final_accounts r LEFT JOIN LATERAL(
  SELECT MD5(STRING_AGG(CONCAT_WS(':',payment_id,amount_paid,payment_date,month_paid),',' ORDER BY payment_id)) AS fingerprint
  FROM public.payments p WHERE p.customer_id=r.customer_id AND p.voided_at IS NULL
   AND COALESCE(p.payment_type,p.legacy_payment_type)='Monthly Fee') p ON TRUE
  WHERE p.fingerprint IS DISTINCT FROM r.payment_fingerprint) THEN
  RAISE EXCEPTION 'Receipts changed. Refresh the review.'; END IF;
 IF EXISTS(SELECT 1 FROM public.audit_logs WHERE source_key LIKE 'final-reconciliation-20260915:%') THEN
  RAISE EXCEPTION 'This batch was already applied. No duplicate corrections allowed.'; END IF;
 IF EXISTS(SELECT 1 FROM final_accounts WHERE target_balance>LEAST(before_balance,0)) THEN
  RAISE EXCEPTION 'Invalid target: existing credit must be preserved and debt cleared'; END IF;
END $$;
SELECT COUNT(*) FILTER(WHERE before_balance>target_balance) AS financial_corrections,
 SUM(before_balance-target_balance) AS credit_to_post,
 COUNT(*) FILTER(WHERE before_status='disconnected') AS reconnections,
 (SELECT COUNT(*) FROM final_schedules) AS schedules_to_convert FROM final_accounts;
 description,created_by_employee_id,reason,is_verified,source_key)
SELECT customer_id,'waiver',target_balance-before_balance,DATE '2026-09-15',
 'Management billing reconciliation',2,
 'One-time management relief for monthly-paying accounts; preserve future payments and convert existing deferred coverage to credit.',TRUE,
 'final-reconciliation-20260915:'||customer_id::TEXT
FROM final_accounts WHERE before_balance>target_balance;
 reviewed_by_employee_id,reviewed_at,review_note,waiver_ledger_entry_id,is_credit)
SELECT r.customer_id,r.before_balance-r.target_balance,
 'One-time management billing reconciliation; cleared debt and preserved advance coverage.',
 'approved',2,2,CURRENT_TIMESTAMP,'Applied by employee 2 under management instruction.',l.account_ledger_entry_id,r.target_balance<0
FROM final_accounts r JOIN public.account_ledger_entries l
 ON l.source_key='final-reconciliation-20260915:'||r.customer_id::TEXT
WHERE r.before_balance>r.target_balance;
UPDATE public.customer_billing_start b SET billing_start_date=DATE '2026-09-15',
 note=CONCAT_WS(E'\n',b.note,'2026-09-15: deferred future coverage converted to ledger credit by employee 2; future anniversary charges resume after September 15.'),
 updated_at=CURRENT_TIMESTAMP FROM final_schedules s WHERE b.customer_id=s.customer_id;
CREATE TEMP TABLE final_queued ON COMMIT DROP AS
WITH moved AS (
 UPDATE public.customers c SET status='pending_reconnection'
 FROM final_accounts r, public.customer_billing_status b
 WHERE c.customer_id=r.customer_id AND b.customer_id=c.customer_id
  AND c.status='disconnected' AND b.ready_for_reconnection RETURNING c.customer_id
), recorded AS (
 SELECT customer_id,'disconnected','pending_reconnection','Management reconciliation: balance cleared; awaiting reconnection',2,
  'final-reconciliation-20260915:reconnect:'||customer_id::TEXT FROM moved
 RETURNING customer_id,account_status_history_id
) SELECT * FROM recorded;
UPDATE public.reconnection_requests r SET status='approved',reviewed_at=CURRENT_TIMESTAMP,
 reviewed_by_employee_id=2,review_note='Balance cleared by management reconciliation.',
 account_status_history_id=q.account_status_history_id FROM final_queued q
WHERE r.customer_id=q.customer_id AND r.status='pending';
SELECT 2,CONCAT_WS(' ',e.first_name,e.last_name),'Management billing reconciliation','customer',r.customer_id::TEXT,
 'balance',r.before_balance::TEXT,r.target_balance::TEXT,
 'One-time debt relief; future receipts and deferred prepaid coverage retained.',
 'final-reconciliation-20260915:'||r.customer_id::TEXT
FROM final_accounts r CROSS JOIN public.employees e WHERE e.employee_id=2 AND r.before_balance>r.target_balance
UNION ALL
SELECT 2,CONCAT_WS(' ',e.first_name,e.last_name),'Converted deferred billing coverage to credit','customer',s.customer_id::TEXT,
 'billing_start_date',s.old_start::TEXT,'2026-09-15','Deferred value preserved: J$'||s.deferred_value::TEXT,
 'final-reconciliation-20260915:schedule:'||s.customer_id::TEXT FROM final_schedules s CROSS JOIN public.employees e WHERE e.employee_id=2
UNION ALL
SELECT 2,CONCAT_WS(' ',e.first_name,e.last_name),'Queued reconnection','customer',q.customer_id::TEXT,
 'status','disconnected','pending_reconnection','Management reconciliation cleared balance.',
 'final-reconciliation-20260915:reconnect:'||q.customer_id::TEXT FROM final_queued q CROSS JOIN public.employees e WHERE e.employee_id=2;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM final_accounts r JOIN public.customer_billing_status b USING(customer_id)
  WHERE b.balance IS DISTINCT FROM r.target_balance) THEN RAISE EXCEPTION 'Balance verification failed'; END IF;
 IF (SELECT COUNT(*) FROM final_queued)<>392 THEN RAISE EXCEPTION 'Expected 392 reconnection transitions'; END IF;
 IF EXISTS(SELECT 1 FROM final_accounts r JOIN public.customers c USING(customer_id)
  WHERE c.status IS DISTINCT FROM CASE WHEN r.before_status='disconnected' THEN 'pending_reconnection' ELSE r.before_status END) THEN
  RAISE EXCEPTION 'Status verification failed'; END IF;
 IF EXISTS(SELECT 1 FROM final_schedules s JOIN public.customer_billing_start b USING(customer_id)
  WHERE b.billing_start_date<>DATE '2026-09-15') THEN RAISE EXCEPTION 'Schedule verification failed'; END IF;
END $$;

-- Prevent newly accepted monthly receipts from losing their excess credit.
-- Keep accepted monthly receipts and the ledger equal while older API builds
-- still cap past-month deductions. The API uses the same payment:<id> key and
-- ON CONFLICT DO NOTHING, so its later insert cannot duplicate this credit.
-- Imported legacy payments retain their paid-through reconstruction semantics.
CREATE OR REPLACE FUNCTION public.spcl_record_full_monthly_receipt()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.customer_id IS NULL OR NEW.payment_type IS DISTINCT FROM 'Monthly Fee'
     OR NEW.amount_paid IS NULL OR NEW.amount_paid <= 0 OR NEW.voided_at IS NOT NULL
     OR NEW.legacy_payment_id IS NOT NULL OR NEW.source_staging_id IS NOT NULL
     OR NEW.recorded_at IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM 1 FROM public.customers WHERE customer_id=NEW.customer_id FOR UPDATE;
    customer_id, entry_type, amount, effective_date, description, payment_id,
    created_by_employee_id, reason, source_key
  ) VALUES (
    NEW.customer_id, 'monthly_payment', -NEW.amount_paid,
    (CURRENT_TIMESTAMP AT TIME ZONE 'America/Jamaica')::DATE,
    'Monthly fee payment', NEW.payment_id, NEW.recorded_by_employee_id,
    'Full receipt credited; any amount beyond outstanding debt remains as credit.',
    'payment:' || NEW.payment_id::TEXT
  ) ON CONFLICT (source_key) DO NOTHING;
  RETURN NEW;
END $$;

CREATE OR REPLACE TRIGGER trg_full_monthly_receipt_credit
AFTER INSERT ON public.payments
FOR EACH ROW EXECUTE FUNCTION public.spcl_record_full_monthly_receipt();

SELECT 'VERIFIED BEFORE COMMIT' AS result,2639 AS balance_corrections,9467380.00 AS total_adjustment,392 AS pending_reconnections,199 AS converted_schedules;
COMMIT;
